	private static string getToyLanguageId(bool bigEndian, bool wordAligned) {
		if (wordAligned) {
			return bigEndian ? TOY_LANGUAGE_ID_BE_ALIGN2 : TOY_LANGUAGE_ID_LE_ALIGN2;
		}
		return bigEndian ? TOY_LANGUAGE_ID_BE : TOY_LANGUAGE_ID_LE;
	}

